<template>
  <main class="ops-page"><header><div><p>密价运营中心</p><h1>套餐与发布规则</h1><p>草稿可调整，发布版本和已生效权益保留；预存金额不是销售收入。</p></div><div class="actions"><el-button :loading="loading" @click="load">刷新</el-button><el-button v-if="can('course-private-plan:manage')" type="primary" @click="edit(null)">新建套餐</el-button><el-button v-if="can('course-private-cost:verify')" @click="openCost">核验真实成本</el-button></div></header>
    <el-alert v-if="error" :title="error" type="error" :closable="false" show-icon />
    <el-tabs v-model="tab"><el-tab-pane v-if="canReadPlans" label="运营套餐" name="plans"><el-card v-loading="loading"><el-form inline @submit.prevent="load"><el-form-item label="课程商品"><el-input v-model="platformFilter" aria-label="套餐课程商品编号" inputmode="numeric" clearable /></el-form-item><el-button native-type="submit">查询</el-button></el-form><el-empty v-if="!plans.length&&!loading" description="暂无套餐，先配置商品与真实成本" /><article v-for="plan in plans" :key="plan.id" class="list-row"><div><h2>{{ plan.planName }}</h2><el-tag>{{ privateState(plan.status) }}</el-tag></div><p>{{ privateMode(plan.mode) }} · {{ plan.planCode }} · {{ plan.visibleToAgents?'代理可见':'指定代理使用' }}</p><p>草稿版本 {{ plan.draftVersion }} · {{ plan.tierCode||'无档位' }} · {{ plan.applicationMode==='AUTO'?'公开首开自动审核':'开通须审核' }}</p><div class="actions"><el-button type="primary" plain @click="view(plan.id)">查看规则与成本</el-button><el-button v-if="can('course-private-plan:manage')&&plan.mode!=='LEGACY_PERMANENT'" @click="edit(plan.id)">编辑草稿</el-button></div></article><el-pagination v-model:current-page="page" :page-size="20" :total="total" layout="total,prev,pager,next" @current-change="load" /></el-card></el-tab-pane>
      <el-tab-pane v-if="canReadCosts" label="成本核验记录" name="costs"><el-card><el-empty v-if="!costs.length" description="暂无已核验成本，不会推测毛利" /><article v-for="cost in costs" :key="cost.id" class="list-row"><div><h2>课程商品 {{ cost.platformId }}</h2><el-tag>{{ cost.status==='VERIFIED'?'已核验':'待核验' }}</el-tag></div><p>成本版本 {{ cost.id }} · 单位成本 ¥{{ privateMoney(cost.unitCost) }}</p><p>{{ cost.evidence }}</p><small>{{ privateDate(cost.verifiedAt) }}</small></article></el-card></el-tab-pane></el-tabs>
    <el-dialog v-model="detailVisible" title="套餐规则与发布历史" width="min(820px,95vw)" append-to-body><el-alert v-if="detailError" :title="detailError" type="error" :closable="false" /><div v-loading="detailLoading" v-if="detail"><h2>{{ detail.plan.planName }}</h2><el-alert v-if="detail.readOnly" title="旧版兼容记录只读，保留原合同价格和有效期，不能转换为新草稿。" type="info" :closable="false" /><template v-else><p v-if="detail.impact">关联协议 {{ detail.impact.relatedContracts }} · 历史周期 {{ detail.impact.relatedPeriods }} · 当前有效协议 {{ detail.impact.activeContracts }}。编辑和发布不会改写这些周期的冻结价格。</p><el-form inline @submit.prevent="loadReference"><el-form-item label="普通价参考代理UUID"><el-input v-model="referenceUid" aria-label="普通价参考代理UUID" clearable /></el-form-item><el-button :loading="referenceLoading" @click="loadReference">计算代理普通价</el-button></el-form><el-alert v-if="referenceError" :title="referenceError" type="error" :closable="false" /><p v-if="reference">该代理普通成交参考价 ¥{{ privateMoney(reference.ordinaryPrice) }}，已保存草稿密价 ¥{{ privateMoney(reference.fixedPrice) }}。参考不构成成交，实际订单须重新报价。</p><el-button v-if="can('course-private-plan:manage')" @click="copyDraft(detail.plan.id)">复制为新草稿</el-button><div class="metrics"><article><span>草稿固定价格</span><strong>¥{{ privateMoney(detail.draftRules.fixedPrice) }}/单</strong></article><article><span>核验单位成本</span><strong>{{ detail.assessment.verifiedUnitCost==null?'数据不足，待核验':`¥${privateMoney(detail.assessment.verifiedUnitCost)}` }}</strong></article><article><span>预计单位贡献</span><strong>{{ detail.assessment.contributionMargin==null?'数据不足':`¥${privateMoney(detail.assessment.contributionMargin)}` }}</strong></article></div><p>{{ ruleSummary(detail.draftRules) }}</p><el-alert v-if="detail.assessment.requiredRiskApproval" title="当前价格不高于核验成本，需要独立审批人批准本草稿及成本版本风险；草稿变更后须重新核验。" type="warning" :closable="false" show-icon /><div class="actions"><el-button v-if="can('course-private-plan:publish')" type="primary" :disabled="!detail.assessment.costVersionId" @click="openAction('publish')">发布本草稿</el-button><el-button v-if="can('course-private-risk:approve')&&detail.assessment.requiredRiskApproval" @click="openAction('risk')">独立批准风险</el-button><el-button v-if="can('course-private-plan:publish')&&detail.plan.status==='PUBLISHED'" type="danger" plain @click="openAction('disable')">停止新销售</el-button></div></template><h3>不可变发布历史</h3><el-empty v-if="!detail.versions?.length" description="尚未发布" /><article v-for="version in detail.versions" :key="version.id" class="list-row"><strong>版本 {{ version.versionNo }} · ¥{{ privateMoney(version.fixedPrice) }}/单</strong><p>首次门槛 ¥{{ privateMoney(version.initialDepositAmount) }} · {{ version.validityDays?`${version.validityDays} 天`:'未设置固定期限' }}</p><small>发布时间 {{ privateDate(version.publishedAt) }}</small></article></div></el-dialog>
    <el-dialog v-model="editorVisible" :title="editingId?'编辑套餐草稿':'新建套餐草稿'" width="min(850px,95vw)" :close-on-click-modal="!busy" :show-close="!busy" append-to-body><el-form label-position="top" class="form-grid"><el-form-item label="绑定课程商品编号"><el-input v-model="draft.platformId" aria-label="草稿绑定课程商品编号" inputmode="numeric" :disabled="busy||!!editingId" /></el-form-item><el-form-item label="套餐编码"><el-input v-model="draft.planCode" aria-label="套餐编码" :disabled="busy||!!editingId" maxlength="64" /></el-form-item><el-form-item label="套餐名称"><el-input v-model="draft.planName" aria-label="套餐名称" :disabled="busy" maxlength="128" /></el-form-item><el-form-item label="运营模式"><el-select v-model="draft.rules.mode" aria-label="运营模式" :disabled="busy" @change="modeChanged"><el-option v-for="mode in modes" :key="mode" :value="mode" :label="privateMode(mode)" /></el-select></el-form-item><el-form-item label="固定价格（元/单）"><el-input v-model="draft.rules.fixedPrice" aria-label="草稿固定价格" inputmode="decimal" :disabled="busy" /></el-form-item><el-form-item label="首次预存本金 N"><el-input v-model="draft.rules.initialDepositAmount" aria-label="首次预存本金" inputmode="decimal" :disabled="busy" /></el-form-item><el-form-item label="首次资格资金政策"><el-select v-model="draft.rules.initialFundingPolicy" aria-label="首次资金政策" :disabled="busy"><el-option value="NEW_DEPOSIT" label="批准后净新增预存" /><el-option value="EXISTING_BALANCE" label="明确允许存量可用余额" /></el-select></el-form-item><el-form-item label="连续权益天数 T"><el-input-number v-model="draft.rules.validityDays" aria-label="权益天数" :min="1" :max="3650" :disabled="busy||draft.rules.mode==='PERMANENT_PREPAID'" /></el-form-item><el-form-item label="续期政策"><el-select v-model="draft.rules.renewalPolicy" aria-label="续期政策" :disabled="busy||['PERMANENT_PREPAID','PERFORMANCE_RENEWAL'].includes(draft.rules.mode)"><el-option value="NONE" label="不续期" /><el-option value="NEW_DEPOSIT" label="净新增预存" /><el-option value="PERFORMANCE" label="有效消费达标" /><el-option value="MANUAL" label="人工补授" /></el-select></el-form-item><el-form-item v-if="draft.rules.renewalPolicy==='NEW_DEPOSIT'" label="每期净新增预存 R"><el-input v-model="draft.rules.renewalDepositAmount" aria-label="续期新增预存" inputmode="decimal" :disabled="busy" /></el-form-item><el-form-item v-if="draft.rules.renewalPolicy==='PERFORMANCE'" label="有效消费目标 M"><el-input v-model="draft.rules.renewalConsumptionTarget" aria-label="续期有效消费目标" inputmode="decimal" :disabled="busy" /></el-form-item><el-form-item label="原订单观察期（天）"><el-input-number v-model="draft.rules.settlementGraceDays" aria-label="结算观察期" :min="0" :max="365" :disabled="busy" /></el-form-item><el-form-item label="续期价格策略"><el-select v-model="draft.rules.renewalPricePolicy" aria-label="续期价格策略" :disabled="busy"><el-option value="SAME_VERSION" label="沿用原确认版本" /><el-option value="LATEST_PUBLISHED" label="下一期起点当时已发布版本" /></el-select></el-form-item><el-form-item label="续期申请窗口（结束前/后天数）"><div class="number-pair"><el-input-number v-model="draft.rules.renewalBeforeDays" aria-label="结束前申请天数" :min="0" :max="3650" :disabled="busy" /><el-input-number v-model="draft.rules.renewalAfterDays" aria-label="结束后申请天数" :min="0" :max="3650" :disabled="busy" /></div></el-form-item><el-form-item label="允许开始时间"><el-date-picker v-model="draft.rules.activationFrom" aria-label="允许开始时间" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss" :disabled="busy" /></el-form-item><el-form-item label="销售有效期"><div class="number-pair"><el-date-picker v-model="draft.rules.effectiveFrom" aria-label="销售开始时间" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss" :disabled="busy" /><el-date-picker v-model="draft.rules.effectiveUntil" aria-label="销售结束时间" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss" :disabled="busy" /></div></el-form-item><el-form-item label="家族编码"><el-input v-model="draft.familyCode" aria-label="档位家族编码" :disabled="busy" /></el-form-item><el-form-item label="档位编码与顺序"><div class="number-pair"><el-input v-model="draft.tierCode" aria-label="档位编码" :disabled="busy" /><el-input-number v-model="draft.tierRank" aria-label="档位顺序" :min="0" :disabled="busy" /></div></el-form-item><el-form-item label="升级生效政策"><el-select v-model="draft.rules.upgradePolicy" aria-label="升级生效政策" :disabled="busy"><el-option value="DISABLED" label="不允许升级" /><el-option value="NEXT_TERM" label="下一期生效" /><el-option value="REVIEW_IMMEDIATE" label="允许独立审核即时升级" /></el-select></el-form-item><el-form-item label="升级资金政策"><el-select v-model="draft.rules.upgradeDepositPolicy" aria-label="升级资金政策" :disabled="busy"><el-option value="DIFFERENCE" label="目标与已证明门槛差额" /><el-option value="FULL_TARGET" label="全额目标新增预存" /><el-option value="EXISTING_BALANCE" label="明确存量余额政策" /></el-select></el-form-item><el-form-item label="可见性与首开审核"><div><el-checkbox v-model="draft.visibleToAgents" :disabled="busy">向代理公开</el-checkbox><el-select v-model="draft.applicationMode" aria-label="首开审核方式" :disabled="busy"><el-option value="REVIEW" label="人工审核开通" /><el-option value="AUTO" label="公开套餐自动首开审核" /></el-select></div></el-form-item><el-form-item label="自动执行与明确授权"><div class="checkboxes"><el-checkbox v-model="draft.rules.renewalAuto" :disabled="busy||['NONE','MANUAL'].includes(draft.rules.renewalPolicy)">允许自动续期</el-checkbox><el-checkbox v-model="draft.rules.allowManualGrant" :disabled="busy||draft.rules.renewalPolicy==='NONE'">允许独立人工补授</el-checkbox><el-checkbox v-model="draft.rules.upgradeAuto" :disabled="busy||draft.rules.upgradePolicy!=='NEXT_TERM'">允许自动下一档升级</el-checkbox><el-checkbox v-model="draft.rules.allowGeneralCheckout" :disabled="busy">允许失效后显式选择普通价</el-checkbox></div></el-form-item><el-form-item label="说明"><el-input v-model="draft.description" aria-label="套餐公开说明" type="textarea" maxlength="2000" :disabled="busy" /></el-form-item><el-form-item label="本次修改原因"><el-input v-model="draft.reason" aria-label="草稿操作原因" maxlength="255" :disabled="busy" /></el-form-item></el-form><el-alert v-if="formError" :title="formError" type="error" :closable="false" /><template #footer><el-button :disabled="busy" @click="editorVisible=false">取消</el-button><el-button type="primary" :loading="busy" @click="save">保存草稿</el-button></template></el-dialog>
    <el-dialog v-model="actionVisible" :title="action==='publish'?'确认发布规则':action==='risk'?'独立风险审批':'停止新销售'" width="min(540px,95vw)" :close-on-click-modal="!busy" :show-close="!busy" append-to-body><p>{{ detail?.plan.planName }} · 草稿版本 {{ detail?.plan.draftVersion }}</p><p>固定价 ¥{{ privateMoney(detail?.draftRules?.fixedPrice) }} · 核验成本 ¥{{ privateMoney(detail?.assessment?.verifiedUnitCost) }}</p><el-alert :title="action==='disable'?'停售阻止新销售，已有周期及约定续期继续保留。':action==='risk'?'风险批准绑定本草稿和成本版本，不能由同一编辑或发布人自行批准。':'发布后版本不可改写，后续调整须保存并发布新版本。'" type="warning" :closable="false" /><el-input v-model="actionReason" aria-label="发布或审批原因" type="textarea" maxlength="255" :disabled="busy" /><el-alert v-if="formError" :title="formError" type="error" :closable="false" /><template #footer><el-button :disabled="busy" @click="actionVisible=false">取消</el-button><el-button type="primary" :loading="busy" @click="submitAction">确认执行</el-button></template></el-dialog>
    <el-dialog v-model="costVisible" title="核验真实单位成本" width="min(540px,95vw)" :close-on-click-modal="!busy" :show-close="!busy" append-to-body><el-alert title="只提交有依据的实际成本；未知成本保持数据不足，不填写猜测值。" type="info" :closable="false" /><el-form label-position="top"><el-form-item label="课程商品编号"><el-input v-model="costForm.platformId" aria-label="成本课程商品编号" inputmode="numeric" :disabled="busy" /></el-form-item><el-form-item label="单位成本（元）"><el-input v-model="costForm.unitCost" aria-label="核验单位成本" inputmode="decimal" :disabled="busy" /></el-form-item><el-form-item label="核验依据"><el-input v-model="costForm.evidence" aria-label="成本核验依据" type="textarea" maxlength="2000" :disabled="busy" /></el-form-item><el-form-item label="核验原因"><el-input v-model="costForm.reason" aria-label="成本核验原因" maxlength="255" :disabled="busy" /></el-form-item><el-form-item label="成本有效期"><el-date-picker v-model="costForm.validFrom" aria-label="成本开始时间" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss" :disabled="busy" /><el-date-picker v-model="costForm.validUntil" aria-label="成本结束时间" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss" :disabled="busy" /></el-form-item></el-form><el-alert v-if="formError" :title="formError" type="error" :closable="false" /><template #footer><el-button :disabled="busy" @click="costVisible=false">取消</el-button><el-button type="primary" :loading="busy" @click="saveCost">保存核验成本</el-button></template></el-dialog>
  </main>
</template>
<script setup>
import {ref,reactive,computed,onMounted} from 'vue';import {ElMessage} from 'element-plus';import * as api from '@/api/coursePrivateOperations';import {sessionUserInfo} from '@/utils/authSession';import {hasPermission,hasAnyPermission} from '@/utils/permissions';import {courseMoney} from '@/utils/courseWallet';import {privateMoney,privateDate,privateState,privateMode} from '@/utils/coursePrivateOperations';
const can=code=>hasPermission(sessionUserInfo.value,code),canReadPlans=computed(()=>hasAnyPermission(sessionUserInfo.value,['course-private-plan:read','course-private-plan:manage','course-private-plan:publish'])),canReadCosts=computed(()=>hasAnyPermission(sessionUserInfo.value,['course-private-cost:verify','course-private-risk:approve','course-private-analytics:read']));
const modes=['PERMANENT_PREPAID','TIME_PREPAID','PERFORMANCE_RENEWAL','TIERED_PRICING'],plans=ref([]),costs=ref([]),page=ref(1),total=ref(0),tab=ref(canReadPlans.value?'plans':'costs'),platformFilter=ref(''),loading=ref(false),error=ref(''),busy=ref(false),formError=ref('');
const referenceUid=ref(''),reference=ref(null),referenceError=ref(''),referenceLoading=ref(false);
const detail=ref(null),detailVisible=ref(false),detailLoading=ref(false),detailError=ref(''),editingId=ref(null),editorVisible=ref(false),draft=reactive({}),actionVisible=ref(false),action=ref(''),actionReason=ref(''),costVisible=ref(false),costForm=reactive({});
const fresh=()=>({platformId:'',planCode:'',planName:'',description:'',familyCode:'STANDARD',tierCode:'',tierRank:0,visibleToAgents:false,applicationMode:'REVIEW',sortOrder:0,expectedDraftVersion:null,reason:'',rules:{mode:'TIME_PREPAID',fixedPrice:'',initialDepositAmount:'0.00',validityDays:30,initialFundingPolicy:'NEW_DEPOSIT',activationFrom:null,renewalPolicy:'NONE',renewalDepositAmount:'0.00',renewalConsumptionTarget:'0.00',settlementGraceDays:7,renewalAuto:false,allowManualGrant:false,renewalPricePolicy:'SAME_VERSION',renewalBeforeDays:7,renewalAfterDays:7,upgradePolicy:'NEXT_TERM',upgradeDepositPolicy:'DIFFERENCE',upgradeAuto:false,allowGeneralCheckout:false,expirationPolicy:'KEEP_BALANCE',effectiveFrom:null,effectiveUntil:null}});
Object.assign(draft,fresh());
const ruleSummary=r=>`${privateMode(r.mode)} · 首次本金 ¥${privateMoney(r.initialDepositAmount)} · ${r.validityDays?`${r.validityDays}天`:'长期'} · 原订单观察期 ${r.settlementGraceDays}天`;
async function load(){loading.value=true;error.value='';try{const params={page:page.value,pageSize:20};if(platformFilter.value.trim())params.platformId=platformFilter.value.trim();if(canReadPlans.value){const response=await api.getAdminPrivatePlans(params);plans.value=response.data.records||[];total.value=response.data.total||0;}if(canReadCosts.value)costs.value=(await api.getPrivateCosts({page:1,pageSize:100,...(params.platformId?{platformId:params.platformId}:{})})).data.records||[];}catch(e){error.value=e.message||'套餐读取失败';}finally{loading.value=false;}}
async function view(id){detailVisible.value=true;detailLoading.value=true;detailError.value='';detail.value=null;reference.value=null;referenceError.value='';try{detail.value=(await api.getAdminPrivatePlan(id)).data;}catch(e){detailError.value=e.message||'规则详情读取失败';}finally{detailLoading.value=false;}}
async function edit(id){if(busy.value)return;formError.value='';editingId.value=id;try{let value=fresh();if(id){const response=(await api.getAdminPrivatePlan(id)).data;if(response.readOnly)throw new Error('旧版兼容记录不可编辑');const plan=response.plan;value={...value,platformId:plan.platformId,planCode:plan.planCode,planName:plan.planName,description:plan.description||'',familyCode:plan.familyCode,tierCode:plan.tierCode||'',tierRank:plan.tierRank,visibleToAgents:plan.visibleToAgents,applicationMode:plan.applicationMode,sortOrder:plan.sortOrder,expectedDraftVersion:plan.draftVersion,rules:{...value.rules,...response.draftRules}};}Object.assign(draft,value);editorVisible.value=true;}catch(e){ElMessage.error(e.message||'草稿读取失败');}}
// 复制重新填写唯一编码，复用保存接口；原发布版本与成本审批不被复制为有效授权。
async function copyDraft(id){await edit(id);if(!editorVisible.value)return;editingId.value=null;draft.planCode='';draft.planName=(draft.planName+' 副本').slice(0,120);draft.expectedDraftVersion=null;draft.reason='复制规则为独立新套餐草稿';detailVisible.value=false;}
async function loadReference(){reference.value=null;referenceError.value='';referenceLoading.value=true;try{reference.value=(await api.getPrivatePlanReference(detail.value.plan.id,referenceUid.value.trim())).data;}catch(e){referenceError.value=e.message||'代理普通价参考读取失败';}finally{referenceLoading.value=false;}}
function modeChanged(){if(draft.rules.mode==='PERMANENT_PREPAID'){draft.rules.validityDays=null;draft.rules.renewalPolicy='NONE';}else {if(!draft.rules.validityDays)draft.rules.validityDays=30;if(draft.rules.mode==='PERFORMANCE_RENEWAL')draft.rules.renewalPolicy='PERFORMANCE';}}
async function save(){if(busy.value)return;formError.value='';try{const body=JSON.parse(JSON.stringify(draft));body.platformId=String(body.platformId).trim();if(!/^[1-9]\d*$/.test(body.platformId)||!body.planName.trim()||!body.reason.trim())throw new Error('请填写合法商品编号、名称及修改原因');body.rules.fixedPrice=courseMoney(body.rules.fixedPrice);if(body.rules.fixedPrice==='0.00')throw new Error('固定价必须大于零');body.rules.initialDepositAmount=courseMoney(body.rules.initialDepositAmount);body.rules.renewalDepositAmount=body.rules.renewalPolicy==='NEW_DEPOSIT'?courseMoney(body.rules.renewalDepositAmount):'0.00';body.rules.renewalConsumptionTarget=body.rules.renewalPolicy==='PERFORMANCE'?courseMoney(body.rules.renewalConsumptionTarget):'0.00';if(['NONE','MANUAL'].includes(body.rules.renewalPolicy))body.rules.renewalAuto=false;if(body.rules.renewalPolicy==='NONE')body.rules.allowManualGrant=false;if(body.rules.upgradePolicy!=='NEXT_TERM')body.rules.upgradeAuto=false;busy.value=true;await api.savePrivatePlan(editingId.value,body);editorVisible.value=false;await load();ElMessage.success('草稿已保存，尚未发布给代理');}catch(e){formError.value=e.message||'草稿保存失败，请刷新版本后重试';}finally{busy.value=false;}}
function openAction(kind){if(busy.value)return;action.value=kind;actionReason.value='';formError.value='';actionVisible.value=true;}
async function submitAction(){if(busy.value)return;formError.value='';try{if(!actionReason.value.trim())throw new Error('请填写明确的操作原因');busy.value=true;const d=detail.value;const body={expectedDraftVersion:d.plan.draftVersion,costVersionId:d.assessment.costVersionId,reason:actionReason.value.trim()};if(action.value==='risk')await api.approvePrivateRisk({planId:d.plan.id,draftVersion:d.plan.draftVersion,costVersionId:d.assessment.costVersionId,reason:body.reason});else if(action.value==='publish')await api.publishPrivatePlan(d.plan.id,body);else await api.disablePrivatePlan(d.plan.id,body);actionVisible.value=false;await view(d.plan.id);await load();ElMessage.success('操作已确认，历史发布版本保留');}catch(e){formError.value=e.message||'操作失败，请核对版本与独立审批';}finally{busy.value=false;}}
function openCost(){formError.value='';Object.assign(costForm,{platformId:platformFilter.value,unitCost:'',evidence:'',reason:'',validFrom:null,validUntil:null});costVisible.value=true;}
async function saveCost(){if(busy.value)return;formError.value='';try{if(!/^[1-9]\d*$/.test(String(costForm.platformId))||!costForm.evidence.trim()||!costForm.reason.trim())throw new Error('请填写商品编号、实际核验依据与原因');busy.value=true;await api.verifyPrivateCost({...costForm,unitCost:courseMoney(costForm.unitCost)});costVisible.value=false;await load();ElMessage.success('核验成本已保存为独立版本');}catch(e){formError.value=e.message||'成本核验失败';}finally{busy.value=false;}}
onMounted(load);
</script>
